/// <summary>
/// This class is to update the claims data with the variance amount.
/// </summary>
class METPendingVendorInvoiceClaimCalculations
{
}

Method.Source:
/// <summary>
/// Creates the claim header and lines data.
/// </summary>
/// <param name = "_invoiceInfoTable">_invoiceInfoTable</param>
public void createClaimData(VendInvoiceInfoTable _invoiceInfoTable)
{
    VendInvoiceInfoLine invoiceInfoLine;
    METMatchingVarianceDetailsHeader header;
    METMatchingVarianceDetailLines lines;

    delete_from header
        where header.PONumber == _invoiceInfoTable.PurchId;

    delete_from lines
        where lines.InvoiceNumber == _invoiceInfoTable.Num
        && lines.VendAccountNumber == _invoiceInfoTable.InvoiceAccount;

    this.createClaimHeader(_invoiceInfoTable);

    LineNumber lineNum;

    while select invoiceInfoLine
        where invoiceInfoLine.ParmId == _invoiceInfoTable.ParmId
        && invoiceInfoLine.TableRefId == _invoiceInfoTable.TableRefId
        && invoiceinfoLine.ReasonTableRef != 0
    {
        lineNum++;
        this.createClaimLines(invoiceInfoLine, _invoiceInfoTable.Num, lineNum);
    }
}

/// <summary>
/// Creates the claim header data.
/// </summary>
/// <param name = "_invoiceInfoTable">_invoiceInfoTable</param>
private void createClaimHeader(VendInvoiceInfoTable _invoiceInfoTable)
{
    METMatchingVarianceDetailsHeader header;

    header.VendAccountNumber = _invoiceInfoTable.InvoiceAccount;
    header.VendorName = VendTable::find(_invoiceInfoTable.InvoiceAccount).vendorName();
    header.InvoiceNumber = _invoiceInfoTable.Num;
    header.PONumber = _invoiceInfoTable.PurchId;
    header.VendInvTotal = _invoiceInfoTable.MetImportAmount - _invoiceInfoTable.MetImportGST;
    header.Variance = _invoiceInfoTable.displayMetVariance();
    header.D365InvoiceTotal = _invoiceInfoTable.MetImportAmount - header.Variance;
    header.IntoleranceVariance = header.Variance;
    header.VendorInvoiceGST = _invoiceInfoTable.MetImportGST;
    header.D365CalculatedGST = _invoiceInfoTable.MetImportGST;
    header.GSTVariance = _invoiceInfoTable.displayMetGSTVariance();
    header.insert();
}

/// <summary>
/// Creates the claim lines data.
/// </summary>
/// <param name = "_invoiceInfoLine">_invoiceInfoLine</param>
/// <param name = "_invoiceId">_invoiceId</param>
/// <param name = "_lineNum">_lineNum</param>
private void createClaimLines(VendInvoiceInfoLine _invoiceInfoLine, InvoiceId _invoiceId, LineNumber _lineNum)
{
    METMatchingVarianceDetailLines lines;
    ReasonTable reason;
    ReasonTableRef reasonTableRef;

    select firstonly Reason, METClaim, METVarianceType from reason
        exists join reasonTableRef
        where reasonTableRef.Reason == reason.Reason
        && reasonTableRef.RecId == _invoiceInfoLine.ReasonTableRef;

    VendInvoiceInfoLine invoiceInfoLine;

    select firstonly invoiceInfoLine
        where invoiceInfoLine.ItemId == _invoiceInfoLine.METVarianceItemId
        && invoiceInfoLine.ParmId == _invoiceInfoLine.ParmId
        && invoiceInfoLine.TableRefId == _invoiceInfoLine.TableRefId;

    lines.clear();
    lines.ReasonCode = reason.Reason;
    lines.VarianceAccount = invoiceInfoLine.METVarianceAccount;
    lines.Claim = reason.METClaim ? NoYes::Yes : NoYes::No;
    lines.ItemNumber = invoiceInfoLine.ItemId;
    lines.ItemDescription = InventTable::find(invoiceInfoLine.ItemId).itemName();

    lines.InvoiceQuantity = invoiceInfoLine.ReceiveNow + _invoiceInfoLine.METQuantityVariance;
    lines.ReceiptedQuantity = invoiceInfoLine.METReceiptedQuantity;
    lines.InvoiceCWQuantity = invoiceInfoLine.PdsCWReceiveNow;
    lines.ReceiptedCWQuantity = invoiceInfoLine.METReceiptedCWQuantity;
    lines.CWQuantityVariance = _invoiceInfoLine.METCWQuantityVariance;
    lines.InvoiceUnitPrice = invoiceInfoLine.PurchPrice + _invoiceInfoLine.METPriceVarianceReal;
    lines.ReceiptedUnit = invoiceInfoLine.METReceiptedUnit;
    lines.InvoiceNumber = _invoiceId;
    lines.VendAccountNumber = invoiceInfoLine.InvoiceAccount;
    lines.InvoiceLineNumber = _lineNum;

    if (reason.METVarianceType == METVarianceType::QuantityVarianceOver || reason.METVarianceType == METVarianceType::QuantityVarianceUnder)
    {
        lines.QuantityVariance = _invoiceInfoLine.METQuantityVariance;
        lines.VarianceAmount = _invoiceInfoLine.METQuantityVariance *  _invoiceInfoLine.PurchPrice;
    }
    else if (reason.METVarianceType == METVarianceType::PriceVarianceOver || reason.METVarianceType == METVarianceType::PriceVarianceUnder)
    {
        lines.PriceVariance = _invoiceInfoLine.METPriceVarianceReal;
        lines.VarianceAmount = _invoiceInfoLine.METPriceVarianceReal * lines.InvoiceQuantity;
    }

    lines.insert();
}
